#include <omp.h>
#include <array>
#include <vector>
#include <cstddef>

void binsBy10Count(std::vector<double> const& x, std::array<size_t, 10> &bins) {
    bins.fill(0);

    #pragma omp parallel
    {
        std::array<size_t, 10> local_bins{};
        const std::ptrdiff_t n = static_cast<std::ptrdiff_t>(x.size());

        #pragma omp for nowait
        for (std::ptrdiff_t i = 0; i < n; ++i) {
            const double v = x[static_cast<std::size_t>(i)];

            std::size_t bin;
            if (v >= 100.0) {
                bin = 9;  // place 100.0 in the last bin
            } else if (v <= 0.0) {
                bin = 0;
            } else {
                bin = static_cast<std::size_t>(v / 10.0);
            }

            ++local_bins[bin];
        }

        #pragma omp critical
        {
            for (std::size_t b = 0; b < 10; ++b) {
                bins[b] += local_bins[b];
            }
        }
    }
}
